css:
/* Recibo de Vencimento / Payslip — Isoft Angola HR.
   A4 portrait, one copy per page, each filling its page (HR, October 2026: larger print, two pages
   per sheet stays legible). Targets wkhtmltopdf (Qt WebKit): tables, pt units,
   no flexbox or grid. Everything is scoped to .rv so no other print format is touched.

   The four .print-format margin declarations below are read by
   frappe.utils.pdf.read_options_from_html and become the wkhtmltopdf page margins, so
   the printable area is the same on every site whatever Print Settings say. */
.print-format {
  margin-top: 10mm;
  margin-bottom: 10mm;
  margin-left: 12mm;
  margin-right: 12mm;
}

/* Frappe's print stylesheet pads .print-format by 0.2in top and bottom in a narrow
   viewport — and wkhtmltopdf's viewport is narrow. The page margins above already
   frame the page; the padding only took ~29pt out of every page and, once a copy was
   full, pushed an empty third page out of the printer. */
@media print {
  .print-format { padding: 0 !important; margin: 0 !important; }
}

.rv {
  font-family: "Liberation Sans", Arial, Helvetica, sans-serif;
  font-size: 11.07pt;
  line-height: 1.25;
  color: #111;
  width: 100%;
  -webkit-print-color-adjust: exact;
}
.rv table { border-collapse: collapse; width: 100%; }
.rv td, .rv th { vertical-align: top !important; }

/* ---- counter Frappe's print stylesheet (padding 6px, grey th, no th border: all
        !important) at the same weight, scoped to the receipt ---- */
.rv td, .rv th { padding: 0 !important; }
.rv th { background-color: transparent !important; border-bottom: 0 !important; }

.rv .rv-strong { font-weight: bold; }
.rv .rv-muted { color: #555; }
.rv .rv-mono { font-family: "Liberation Mono", "DejaVu Sans Mono", monospace; letter-spacing: 0.27pt; }

/* ---- copies ---- */
.rv .rv-break { page-break-before: always; }

/* ---- header ---- */
.rv .rv-head { margin-bottom: 6.75pt; border-bottom: 2.16pt solid #1a1a1a; }
.rv .rv-head td { padding: 0 0 6.75pt 0 !important; }
.rv .rv-head-co { width: 50%; }
.rv .rv-head-doc { width: 50%; text-align: right; }
.rv .rv-co { width: auto; }
.rv .rv-co td { padding: 0 !important; vertical-align: middle !important; }
/* An explicit cell width: Frappe's print stylesheet gives every image max-width:100%,
   and 100% of an auto-sized cell is whatever WebKit felt like — once it was 1.35pt. */
.rv .rv-co-name { font-size: 16.88pt; font-weight: bold; letter-spacing: 0.41pt; margin-bottom: 2.03pt; }
.rv .rv-co-line { font-size: 10.8pt; word-wrap: break-word; }
.rv .rv-title {
  font-size: 18.9pt; font-weight: bold; letter-spacing: 1.35pt; text-transform: uppercase;
  color: #1a1a1a; margin-bottom: 4.05pt; white-space: nowrap;
}
.rv .rv-copy-label {
  display: inline-block; border: 1.35pt solid #1a1a1a; padding: 2.03pt 8.1pt !important;
  font-size: 10.26pt; font-weight: bold; letter-spacing: 1.08pt; text-transform: uppercase;
  margin-bottom: 6.75pt; white-space: nowrap;
}
.rv .rv-doc-meta { width: auto; margin-left: auto; }
.rv .rv-doc-meta td { padding: 0.81pt 0 !important; font-size: 10.8pt; }
.rv .rv-doc-meta .k { color: #555; padding-right: 10.8pt !important; text-align: right; }
.rv .rv-doc-meta .v { font-weight: bold; text-align: right; white-space: nowrap; }

/* ---- stamps ---- */
.rv .rv-stamp {
  border: 1.62pt solid #b00020; color: #b00020; padding: 4.05pt 8.1pt !important; margin: 0 0 9.45pt 0;
  font-weight: bold; font-size: 12.15pt; text-align: center; letter-spacing: 2.03pt;
}

/* ---- section captions ---- */
.rv .rv-sec-title {
  font-size: 10.26pt; font-weight: bold; text-transform: uppercase; letter-spacing: 1.22pt;
  color: #333; background: #ededed; padding: 2.43pt 6.75pt; margin: 5.4pt 0 2.7pt 0;
  border-left: 3.24pt solid #1a1a1a;
}

/* ---- key / value grid ---- */
.rv .rv-kv td { padding: 2.03pt 5.4pt !important; border-bottom: 0.68pt solid #dcdcdc; font-size: 10.8pt; }
.rv .rv-kv .k { width: 16%; color: #555; }
.rv .rv-kv .v { width: 34%; word-wrap: break-word; }
.rv .rv-kv-1 .k { width: 38%; }
.rv .rv-kv-1 .v { width: 62%; }

/* ---- processing stat boxes ---- */
.rv .rv-stats td {
  padding: 3.38pt 6.75pt !important; border: 0.81pt solid #cfcfcf; background: #fafafa;
  text-align: center; width: 20%;
}
.rv .rv-stats .k { font-size: 9.45pt; color: #555; text-transform: uppercase; letter-spacing: 0.54pt; }
.rv .rv-stats .v { font-size: 12.42pt; font-weight: bold; margin-top: 1.35pt; white-space: nowrap; }

/* ---- earnings / deductions ---- */
.rv .rv-lines { table-layout: fixed; margin-bottom: 2.7pt; }
.rv .rv-lines thead { display: table-header-group; }
.rv .rv-lines th {
  font-size: 9.99pt; font-weight: bold; text-transform: uppercase; letter-spacing: 0.68pt;
  color: #333; text-align: left; padding: 2.7pt 6.75pt !important;
  border-top: 1.22pt solid #1a1a1a; border-bottom: 1.22pt solid #1a1a1a !important;
}
.rv .rv-lines td { padding: 2.43pt 6.75pt !important; border-bottom: 0.68pt solid #dcdcdc; word-wrap: break-word; }
.rv .rv-lines .c-code { width: 13%; white-space: nowrap; }
.rv .rv-lines .c-desc { width: 59%; }
.rv .rv-lines .c-amt { width: 28%; text-align: right; white-space: nowrap; }
.rv .rv-lines th.c-amt { text-align: right; }
.rv .rv-lines .rv-memo td { color: #666; font-style: italic; }
.rv .rv-lines .rv-memo-tag { font-size: 9.45pt; }
.rv .rv-lines .rv-empty td { text-align: center; color: #888; }
.rv .rv-lines tfoot .rv-total td {
  font-weight: bold; border-top: 1.22pt solid #1a1a1a; border-bottom: 0; padding-top: 3.38pt !important;
  text-align: right;
}
.rv .rv-lines tr { page-break-inside: avoid; }

/* ---- warning ---- */
.rv .rv-warn {
  border: 1.35pt solid #b00020; color: #b00020; padding: 4.05pt 8.1pt !important; margin: 8.1pt 0 0 0;
  font-weight: bold; font-size: 10.53pt;
}

/* ---- payment + summary ---- */
.rv .rv-bottom { margin-top: 2.7pt; page-break-inside: avoid; }
.rv .rv-bottom > tbody > tr > td { padding: 0 !important; }
.rv .rv-pay { width: 50%; padding-right: 13.5pt !important; }
.rv .rv-sum { width: 50%; padding-left: 13.5pt !important; }
.rv .rv-summary td { padding: 2.29pt 6.75pt !important; border-bottom: 0.68pt solid #dcdcdc; font-size: 11.07pt; }
.rv .rv-summary .k { color: #333; }
.rv .rv-summary .v { text-align: right; white-space: nowrap; font-weight: bold; width: 38%; }
.rv .rv-summary .rv-net td {
  background: #1a1a1a; color: #fff; font-weight: bold; font-size: 13.23pt;
  padding: 5.4pt 8.1pt !important; border-bottom: 0; text-transform: uppercase; letter-spacing: 0.68pt;
}
.rv .rv-summary .rv-net .k { color: #fff; white-space: nowrap; }

/* ---- confirmation ---- */
.rv .rv-decl { font-style: italic; margin: 2.7pt 0 10.8pt 0; padding: 0 5.4pt; }
.rv .rv-sign { page-break-inside: avoid; }
.rv .rv-sign td { padding: 0 !important; }
.rv .rv-sign-l { width: 55%; }
.rv .rv-sign-gap { width: 45%; }
.rv .rv-sign-line { border-bottom: 1.08pt solid #1a1a1a; height: 14.85pt; }
.rv .rv-sign-cap { font-size: 10.26pt; color: #333; margin-top: 2.7pt; }

/* ---- footer ---- */
.rv .rv-foot { margin-top: 6.75pt; border-top: 0.68pt solid #bbb; }
.rv .rv-foot td { padding: 2.7pt 0 0 0 !important; font-size: 9.18pt; color: #666; }
.rv .rv-foot-r { text-align: right; }

@media print {
  .rv table, .rv tr { page-break-inside: avoid; }
  .rv thead { display: table-header-group; }
}

/* ---- each copy fills its page (HR, October 2026) ----
   A fixed-height table: the content sits at the top, the confirmation and the footer at
   the bottom. Sizes above are the September layout scaled by 1.35 so the content itself
   is larger; the height is the printable A4 height inside the page margins above. */
.rv .rv-page { width: 100%; height: 272mm; }
.rv .rv-page td.rv-page-main { vertical-align: top !important; }
.rv .rv-page td.rv-page-end { vertical-align: bottom !important; height: 1px; }

/* Key/value tables at the larger size: labels on one line, and the IBAN (monospaced, 25
   characters) kept inside the payment column. */
.rv .rv-kv td { font-size: 10.2pt; }
.rv .rv-kv .k { width: 22%; }
.rv .rv-kv .v { width: 28%; }
.rv .rv-kv-1 { table-layout: fixed; }
.rv .rv-kv-1 .k { width: 40%; font-size: 9.6pt; }
.rv .rv-kv-1 .v { width: 60%; }
.rv .rv-kv td.rv-mono { font-size: 9.2pt; letter-spacing: 0; white-space: nowrap; }
.rv .rv-pay { width: 53%; }
/* The title and the header labels: wide enough to read, never wider than their column
   (a long title once pushed the whole page past the A4 width). */
.rv .rv-title { font-size: 16pt; letter-spacing: .6pt; }
.rv .rv-doc-meta .k { white-space: nowrap; }
.rv .rv-sum { width: 47%; }
